:root {
  --bg: #1b1f2a;
  --card: #2a3040;
  --ink: #f2f4f8;
  --muted: #a9b1c4;
  --green: #3ecf8e;
  --red: #ef5f6b;
  --yellow: #f2c14e;
  --blue: #4d8bf0;
  --accent: #ffb703;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  background:
    radial-gradient(circle at 20% 10%, #2d3448 0%, transparent 45%),
    radial-gradient(circle at 85% 90%, #232a3a 0%, transparent 50%),
    var(--bg);
  color: var(--ink);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 18px;
  padding: 28px 24px 32px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  text-align: center;
}

h1 {
  margin: 0 0 12px;
  font-size: 1.75rem;
  letter-spacing: 0.02em;
}

.status {
  margin: 0 0 4px;
  font-size: 1.05rem;
  color: var(--muted);
  min-height: 1.5em;
}

.status.is-error { color: var(--red); font-weight: 600; }

.level {
  margin: 0 0 20px;
  font-size: 1rem;
  color: var(--muted);
}

.level span {
  color: var(--accent);
  font-weight: 700;
  font-size: 1.2rem;
}

.board {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 0 auto 24px;
  max-width: 320px;
}

.pad {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 14px;
  cursor: pointer;
  opacity: 0.55;
  transition: transform 0.08s ease, opacity 0.12s ease, box-shadow 0.12s ease;
  box-shadow: inset 0 0 0 3px rgba(0, 0, 0, 0.15);
  padding: 0;
}

.pad--green { background: var(--green); }
.pad--red { background: var(--red); }
.pad--yellow { background: var(--yellow); }
.pad--blue { background: var(--blue); }

.pad:hover:not(:disabled) { opacity: 0.8; }

.pad:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.pad:active:not(:disabled) { transform: scale(0.96); }

.pad.is-lit {
  opacity: 1;
  transform: scale(1.04);
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.35), 0 0 24px rgba(255, 255, 255, 0.35);
}

.pad:disabled { cursor: default; }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 12px 28px;
  border-radius: 10px;
  border: 2px solid var(--muted);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background 0.12s ease, transform 0.08s ease, border-color 0.12s ease;
}

.btn:hover { background: rgba(255, 255, 255, 0.08); border-color: var(--ink); }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
.btn:active { transform: scale(0.97); }

.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #1b1f2a;
}

.btn--primary:hover { background: #ffc533; border-color: #ffc533; }

@media (max-width: 380px) {
  .card { padding: 22px 16px 26px; }
  h1 { font-size: 1.5rem; }
  .btn { padding: 12px 20px; }
}

(function () {
  "use strict";

  var PAD_COUNT = 4;
  var statusEl = document.getElementById("status");
  var levelEl = document.getElementById("level");
  var boardEl = document.getElementById("board");
  var startBtn = document.getElementById("start");
  var restartBtn = document.getElementById("restart");
  var pads = Array.prototype.slice.call(document.querySelectorAll(".pad"));

  var sequence = [];
  var inputIndex = 0;
  var level = 0;
  var acceptingInput = false;
  var playing = false;
  var timers = [];

  function setStatus(text, isError) {
    statusEl.textContent = text;
    statusEl.classList.toggle("is-error", !!isError);
  }

  function clearTimers() {
    timers.forEach(function (t) { clearTimeout(t); });
    timers = [];
  }

  function setPadsDisabled(disabled) {
    pads.forEach(function (p) { p.disabled = disabled; });
  }

  function flashPad(index, duration) {
    var pad = pads[index];
    pad.classList.add("is-lit");
    var t = setTimeout(function () {
      pad.classList.remove("is-lit");
    }, duration);
    timers.push(t);
  }

  function playSequence() {
    acceptingInput = false;
    setPadsDisabled(true);
    setStatus("Watch the sequence...");
    var speed = Math.max(280, 650 - level * 30);
    var gap = speed * 0.55;

    sequence.forEach(function (padIndex, i) {
      var on = setTimeout(function () {
        flashPad(padIndex, speed * 0.6);
      }, i * (speed + gap));
      timers.push(on);
    });

    var total = sequence.length * (speed + gap);
    var done = setTimeout(function () {
      setPadsDisabled(false);
      acceptingInput = true;
      inputIndex = 0;
      setStatus("Your turn!");
    }, total);
    timers.push(done);
  }

  function nextRound() {
    level += 1;
    levelEl.textContent = String(level);
    sequence.push(Math.floor(Math.random() * PAD_COUNT));
    playSequence();
  }

  function startGame() {
    clearTimers();
    sequence = [];
    level = 0;
    inputIndex = 0;
    playing = true;
    acceptingInput = false;
    levelEl.textContent = "0";
    startBtn.hidden = true;
    restartBtn.hidden = true;
    nextRound();
  }

  function gameOver() {
    clearTimers();
    playing = false;
    acceptingInput = false;
    setPadsDisabled(true);
    setStatus("Game over", true);
    restartBtn.hidden = false;
    restartBtn.focus();
  }

  function handlePadPress(index) {
    if (!acceptingInput || !playing) return;
    flashPad(index, 200);

    if (sequence[inputIndex] !== index) {
      gameOver();
      return;
    }

    inputIndex += 1;
    if (inputIndex === sequence.length) {
      acceptingInput = false;
      setPadsDisabled(true);
      setStatus("Nice! Next level...");
      var t = setTimeout(nextRound, 800);
      timers.push(t);
    }
  }

  pads.forEach(function (pad) {
    pad.addEventListener("click", function () {
      handlePadPress(parseInt(pad.getAttribute("data-index"), 10));
    });
  });

  startBtn.addEventListener("click", startGame);
  restartBtn.addEventListener("click", startGame);

  boardEl.addEventListener("keydown", function (e) {
    var idx = pads.indexOf(document.activeElement);
    if (idx === -1) return;
    var next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (idx + 1) % PAD_COUNT;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (idx - 1 + PAD_COUNT) % PAD_COUNT;
    if (next !== -1) {
      e.preventDefault();
      pads[next].focus();
    }
  });

  setPadsDisabled(true);
})();
